// Rivers and climate post-processing against the pinned OpenTTD 15.3 binary.
//
// The fixtures were generated by re/openttd/tools/oracle.mjs with
// OTTD_ORACLE_STAGES=landscape, so no towns, industries, objects or trees
// exist: every tile of the map, including rivers, coasts and their exact
// random bits, must match the native generator byte for byte.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { defaultGeneration, Landscape } from '../src/sim/settings.ts';
import { generateWorld } from '../src/sim/worldgen.ts';

const dir = join(import.meta.dirname, 'fixtures');
const fixtures = [
  'rivers-temperate-12345.json',
  'rivers-tropic-12345.json',
  'rivers-temperate-2-3rivers.json',
];

for (const name of fixtures) {
  test(`${name} matches the native 15.3 map`, () => {
    const fixture = JSON.parse(readFileSync(join(dir, name), 'utf8'));
    const size = fixture.mapSize;
    assert.equal(size, 256);
    assert.equal(fixture.stages, 'landscape');

    const nativeH = Buffer.from(fixture.height, 'base64');
    const nativeT = Buffer.from(fixture.type, 'base64');
    const nativeM1 = Buffer.from(fixture.m1, 'base64');
    const nativeM3 = Buffer.from(fixture.m3, 'base64');
    const nativeM4 = Buffer.from(fixture.m4, 'base64');
    const nativeM5 = Buffer.from(fixture.m5, 'base64');
    for (const array of [nativeH, nativeT, nativeM1, nativeM3, nativeM4, nativeM5]) {
      assert.equal(array.length, size * size);
    }

    const settings = defaultGeneration(fixture.seed);
    settings.landscape = Landscape[fixture.landscape[0].toUpperCase() + fixture.landscape.slice(1) as keyof typeof Landscape];
    settings.terrainType = 1;
    settings.tgenSmoothness = 1;
    settings.variety = 0;
    settings.quantitySeaLakes = 0;
    settings.mapHeightLimit = 0;
    settings.freeformEdges = true;
    settings.waterBorders = 16;
    settings.amountOfRivers = fixture.amountOfRivers;
    settings.treePlacer = 0;

    const { world } = generateWorld(settings);
    assert.equal(world.size, size * size);

    const errors: string[] = [];
    for (let i = 0; i < world.size; i++) {
      const x = i % size, y = Math.floor(i / size);
      if (world.height[i] !== nativeH[i]) errors.push(`${x},${y}: height ${world.height[i]}/${nativeH[i]}`);
      else if (world.type[i] !== nativeT[i]) errors.push(`${x},${y}: type ${world.type[i]}/${nativeT[i]}`);
      else if (world.m1[i] !== nativeM1[i] || world.m3[i] !== nativeM3[i] ||
               world.m4[i] !== nativeM4[i] || world.m5[i] !== nativeM5[i]) {
        errors.push(`${x},${y}: m1 ${world.m1[i]}/${nativeM1[i]} m3 ${world.m3[i]}/${nativeM3[i]} m4 ${world.m4[i]}/${nativeM4[i]} m5 ${world.m5[i]}/${nativeM5[i]}`);
      }
      if (errors.length >= 8) break;
    }
    assert.deepEqual(errors, [], `${name}: tiles differ from the native map`);
  });
}
